INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 29, 'theory', 'Quiz: Node.js Internals');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 0, 'What runs first after the current callback?', '["process.nextTick and then promise microtasks", "setTimeout(…, 0)", "setImmediate", "All of them at once"]', 0, 'Between callbacks the loop drains the nextTick queue, then the microtasks, and repeats until both are empty.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 1, 'Which of these runs in the libuv thread pool?', '["Network sockets", "Running JavaScript", "Timers", "File operations, DNS lookup, zlib"]', 3, 'Sockets use kernel mechanisms (epoll, kqueue); files, dns.lookup, zlib and part of crypto use the pool, which has four threads by default.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 2, 'What does the exports field in package.json do?', '["A list of files to publish", "Installs dependencies", "Defines the package''s public entry points by conditions; anything not listed is closed", "Enables TypeScript"]', 2, 'Apart from the entry points listed in exports, no other files of the package can be imported from outside.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 3, 'What is the exit code of a process terminated by SIGTERM (signal number 15)?', '["0", "143", "15", "255"]', 1, 'By convention it is 128 + the signal number: 128 + 15 = 143.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 4, 'How should a service shut down on SIGTERM?', '["Call process.exit() right away", "Ignore the signal", "Restart the process", "Stop accepting connections, wait for current requests, close resources, exit — all within a timeout"]', 3, 'Graceful shutdown does not cut requests off; a repeated signal or a timeout is a reason to exit forcibly.');
